import io.auralis.core.model.Track;
import javafx.application.Platform;
import javafx.scene.canvas.Canvas;
import javafx.scene.control.*;
import javafx.scene.layout.*;
import javafx.scene.media.*;
import javafx.scene.paint.Color;
import javafx.stage.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.*;
import static io.auralis.desktop.ui.Views.*;

/** An immutable edit decision list plus independent rendered preview. Originals are never outputs. */
public final class EditorView implements AutoCloseable {
    private final LibraryService library;
    private final ExecutorService worker;
    private final Consumer<String> error,status;
    private final Stage owner;
    private final AudioEditor audio;
    private javafx.scene.paint.Color waveAccent=javafx.scene.paint.Color.web("#f8d34a"),waveBackground=javafx.scene.paint.Color.web("#111216"),waveLine=javafx.scene.paint.Color.web("#353535");
    public void setTheme(Theme theme){waveAccent=theme.accentColor();waveBackground=javafx.scene.paint.Color.web(theme.panel());waveLine=javafx.scene.paint.Color.web(theme.surface());draw();}
    private EditSession session;
    private MediaPlayer preview;
    private Path rendered;
    private double[] peaks=new double[0];
    private Canvas canvas;
    private TextField from,to;
    private TextField fadeIn,fadeOut,cross;
    private Slider speed,pitch;
    private final Map<EditProject.Effect,CheckBox> effects=new LinkedHashMap<>();
    private Label projectInfo,renderInfo;
    private Button play,undo,redo;
    private long generation;
    public EditorView(LibraryService library,ExecutorService worker,Consumer<String> error,Consumer<String> status,Stage owner){this.library=library;this.worker=worker;this.error=error;this.status=status;this.owner=owner;audio=new AudioEditor(library.audio());}
    public VBox open(Track track){closePreview();session=new EditSession(EditProject.of(track.path(),track.durationSeconds()));canvas=new Canvas(820,190);from=new TextField("0.00");to=new TextField("%.2f".formatted(track.durationSeconds()).replace(',','.'));from.setPrefWidth(90);to.setPrefWidth(90);projectInfo=label("","muted");renderInfo=label("Подготовка волновой формы…","muted");play=button("▶  Предпрослушать","primary",this::togglePreview);play.setDisable(true);undo=button("↶ Отменить","secondary",()->{session.undo();changed();});redo=button("↷ Повторить","secondary",()->{session.redo();changed();});
        StackPane waveform=new StackPane(canvas);waveform.getStyleClass().add("card");waveform.setMinWidth(0);waveform.widthProperty().addListener((o,a,b)->{canvas.setWidth(Math.max(100,b.doubleValue()-34));draw();});canvas.setOnMousePressed(e->{double value=timeAt(e.getX());from.setText(number(value));to.setText(number(value));draw();});canvas.setOnMouseDragged(e->{to.setText(number(timeAt(e.getX())));draw();});canvas.setOnMouseReleased(e->{try{double a=number(from),b=number(to);from.setText(number(Math.min(a,b)));to.setText(number(Math.max(a,b)));draw();}catch(Exception ignored){}});from.textProperty().addListener((o,a,b)->draw());to.textProperty().addListener((o,a,b)->draw());
        TextField gain=new TextField("0");gain.setPrefWidth(75);TextField insertion=new TextField("0");insertion.setPrefWidth(75);speed=new Slider(.5,2,1);pitch=new Slider(-12,12,0);Label speedValue=label("1.00×","muted"),pitchValue=label("0 st","muted");speed.valueProperty().addListener((o,a,b)->speedValue.setText(number(b.doubleValue())+"×"));pitch.valueProperty().addListener((o,a,b)->pitchValue.setText(number(b.doubleValue())+" st"));fadeIn=new TextField("0");fadeOut=new TextField("0");cross=new TextField("0");for(TextField field:List.of(fadeIn,fadeOut,cross))field.setPrefWidth(70);effects.clear();FlowPane effectsRow=new FlowPane(16,10);for(var effect:EditProject.Effect.values()){CheckBox checkbox=new CheckBox(effect.toString());effects.put(effect,checkbox);effectsRow.getChildren().add(checkbox);}
        VBox page=page("Аудиостудия",track.title()+" — "+track.artist(),tools(label("НЕРАЗРУШАЮЩИЙ ПРОЕКТ","eyebrow"),spacer(),undo,redo),waveform,renderInfo,tools(label("От, сек","muted"),from,label("До, сек","muted"),to,button("Выделить всё","secondary",()->{from.setText("0");to.setText(number(session.project().sourceTimelineSeconds()));draw();})),tools(button("Обрезать","secondary",()->edit(p->audio.trim(p,number(from),number(to)))),button("Удалить диапазон","secondary",()->edit(p->audio.deleteRange(p,number(from),number(to)))),button("Заменить файлом","secondary",()->insertFile(true)),button("Вставить файл","secondary",()->insertFile(false))),tools(label("Вставить в, сек","muted"),insertion,button("Копировать сюда","secondary",()->edit(p->audio.copyRange(p,number(from),number(to),number(insertion)))),button("Переместить сюда","secondary",()->edit(p->audio.moveRange(p,number(from),number(to),number(insertion)))),label("Усиление, dB","muted"),gain,button("Применить к диапазону","secondary",()->edit(p->audio.gainRange(p,number(from),number(to),number(gain))))),card(label("Скорость и тональность","section-title"),tools(label("Time Stretch","muted"),speed,speedValue),tools(label("Pitch Shift","muted"),pitch,pitchValue),tools(label("Fade In, сек","muted"),fadeIn,label("Fade Out","muted"),fadeOut,label("Crossfade","muted"),cross),effectsRow,button("Применить параметры","secondary",()->edit(p->p.withSpeed(speed.getValue()).withPitchSemitones(pitch.getValue()).withFades(number(fadeIn),number(fadeOut)).withCrossfade(number(cross)).withEffects(effects.entrySet().stream().filter(e->e.getValue().isSelected()).map(Map.Entry::getKey).toList())))),projectInfo,tools(play,button("Сохранить проект","secondary",this::saveProject),button("Открыть проект","secondary",this::loadProject),spacer(),button("Экспорт аудио  ↗","primary",this::export)),label("Диапазоны задаются в секундах исходной монтажной шкалы до Time Stretch. Волна показывает результат последнего рендера. Для точного редактирования сначала завершите монтаж, затем применяйте скорость и переходы. Исходный файл не изменяется.","muted"));page.setMinWidth(0);changed();return page;
    }
    private static FlowPane tools(javafx.scene.Node...nodes){FlowPane flow=new FlowPane(12,12,nodes);flow.setAlignment(javafx.geometry.Pos.CENTER_LEFT);flow.setMinWidth(0);return flow;}
    public void pausePreview(){if(preview!=null)preview.pause();}
    private String number(double value){return String.format(Locale.ROOT,"%.2f",value);}
    private double number(TextField field){double value=Double.parseDouble(field.getText().replace(',','.'));if(!Double.isFinite(value))throw new IllegalArgumentException("Введите конечное число");return value;}
    private double timeAt(double x){return Math.clamp(x/canvas.getWidth(),0,1)*session.project().sourceTimelineSeconds();}
    private void draw(){if(canvas==null)return;var g=canvas.getGraphicsContext2D();double w=canvas.getWidth(),h=canvas.getHeight();g.setFill(waveBackground);g.fillRect(0,0,w,h);g.setStroke(waveLine);g.strokeLine(0,h/2,w,h/2);g.setStroke(waveAccent);for(int i=0;i<peaks.length;i++){double x=i*w/peaks.length,y=Math.max(1,peaks[i]*(h*.43));g.strokeLine(x,h/2-y,x,h/2+y);}try{double duration=session.project().sourceTimelineSeconds();double a=number(from)/duration*w,b=number(to)/duration*w;g.setFill(waveAccent.deriveColor(0,1,1,.17));g.fillRect(Math.min(a,b),0,Math.abs(b-a),h);g.setStroke(waveAccent.interpolate(Color.WHITE,.35));g.strokeLine(a,0,a,h);g.strokeLine(b,0,b,h);}catch(Exception ignored){} }
    private void edit(UnaryOperator<EditProject> operation){try{session.apply(operation);from.setText("0");to.setText(number(session.project().sourceTimelineSeconds()));changed();}catch(Exception e){error.accept(e.getMessage());}}
    private void changed(){EditProject project=session.project();speed.setValue(project.speed());pitch.setValue(project.pitchSemitones());fadeIn.setText(number(project.fadeInSeconds()));fadeOut.setText(number(project.fadeOutSeconds()));cross.setText(number(project.crossfadeSeconds()));effects.forEach((effect,checkbox)->checkbox.setSelected(project.effects().contains(effect)));undo.setDisable(!session.canUndo());redo.setDisable(!session.canRedo());projectInfo.setText(project.clips().size()+" фрагментов · результат "+number(project.durationSeconds())+" сек · оригинал сохранён");render();}
    private void render(){long request=++generation;EditProject project=session.project();play.setDisable(true);renderInfo.setText("Рендер предпрослушивания и анализ…");closePreview();worker.submit(()->{try{Path folder=library.dataDirectory().resolve("editor-preview");Files.createDirectories(folder);String id=UUID.randomUUID().toString();Path output=folder.resolve(id+".wav"),raw=folder.resolve(id+".render.wav");try{audio.export(project,raw,AudioEditor.ExportFormat.WAV);library.audio().playbackCopy(raw,output);}finally{Files.deleteIfExists(raw);}double[] waveform=library.audio().waveform(output,1000);Platform.runLater(()->{if(request!=generation){deletePreview(output);return;}Path previous=rendered;rendered=output;deletePreview(previous);peaks=waveform;draw();renderInfo.setText("Предпрослушивание готово · PCM 16 bit / 48 kHz · изменения применены");play.setDisable(false);});}catch(Exception e){Platform.runLater(()->{if(request==generation){renderInfo.setText("Не удалось подготовить звук");error.accept(e.getMessage());}});}});}
    private void togglePreview(){try{if(rendered==null)return;if(preview!=null&&preview.getStatus()==MediaPlayer.Status.PLAYING){preview.pause();return;}if(preview==null){MediaPlayer active=new MediaPlayer(new Media(rendered.toUri().toString()));preview=active;active.setOnReady(()->{if(preview==active)active.play();});active.setOnError(()->{if(preview==active)error.accept(active.getError().getMessage());});active.statusProperty().addListener((o,a,b)->{if(preview==active)play.setText(b==MediaPlayer.Status.PLAYING?"Ⅱ  Пауза":"▶  Предпрослушать");});active.setOnEndOfMedia(()->{if(preview==active)active.seek(javafx.util.Duration.ZERO);});}else preview.play();}catch(Exception e){error.accept(e.getMessage());}}
    private void insertFile(boolean replace){FileChooser chooser=new FileChooser();chooser.setTitle(replace?"Заменить выделение":"Вставить аудиофайл");java.io.File file=chooser.showOpenDialog(owner);if(file==null)return;EditProject project=session.project();long revision=generation;double a,b;try{a=number(from);b=number(to);}catch(Exception e){error.accept(e.getMessage());return;}worker.submit(()->{try{double duration=library.audio().probe(file.toPath()).durationSeconds();EditProject updated=replace?audio.replace(project,a,b,file.toPath(),0,duration):audio.insert(project,a,file.toPath(),0,duration);Platform.runLater(()->{if(revision!=generation){error.accept("Проект изменился во время чтения файла. Повторите вставку в текущую версию.");return;}session.setProject(updated);from.setText("0");to.setText(number(updated.sourceTimelineSeconds()));changed();});}catch(Exception e){Platform.runLater(()->error.accept(e.getMessage()));}});}
    private void saveProject(){FileChooser chooser=new FileChooser();chooser.setInitialFileName("my-version.auralis.json");java.io.File file=chooser.showSaveDialog(owner);if(file==null)return;EditProject project=session.project();worker.submit(()->{try{audio.saveProject(project,file.toPath());Platform.runLater(()->status.accept("Проект сохранён: "+file));}catch(Exception e){Platform.runLater(()->error.accept(e.getMessage()));}});}
    private void loadProject(){FileChooser chooser=new FileChooser();chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("Проект Auralis","*.json"));java.io.File file=chooser.showOpenDialog(owner);if(file==null)return;worker.submit(()->{try{EditProject project=audio.loadProject(file.toPath());Platform.runLater(()->{session=new EditSession(project);from.setText("0");to.setText(number(project.sourceTimelineSeconds()));changed();});}catch(Exception e){Platform.runLater(()->error.accept(e.getMessage()));}});}
    private void export(){FileChooser chooser=new FileChooser();chooser.setInitialFileName("my-version.wav");chooser.getExtensionFilters().addAll(new FileChooser.ExtensionFilter("WAV","*.wav"),new FileChooser.ExtensionFilter("FLAC","*.flac"),new FileChooser.ExtensionFilter("MP3","*.mp3"));java.io.File file=chooser.showSaveDialog(owner);if(file==null)return;String name=file.getName().toLowerCase(Locale.ROOT);AudioEditor.ExportFormat format=name.endsWith(".flac")?AudioEditor.ExportFormat.FLAC:name.endsWith(".mp3")?AudioEditor.ExportFormat.MP3:AudioEditor.ExportFormat.WAV;EditProject project=session.project();status.accept("Экспорт аудио…");worker.submit(()->{try{audio.export(project,file.toPath(),format);Platform.runLater(()->status.accept("Аудио сохранено: "+file));}catch(Exception e){Platform.runLater(()->error.accept(e.getMessage()));}});}
    private void closePreview(){MediaPlayer old=preview;preview=null;if(old!=null){old.setOnReady(null);old.setOnError(null);old.setOnEndOfMedia(null);old.stop();old.dispose();}if(play!=null)play.setText("▶  Предпрослушать");}
    private void deletePreview(Path path){if(path!=null)worker.submit(()->{try{Files.deleteIfExists(path);}catch(Exception ignored){}});}
    @Override public void close(){generation++;closePreview();deletePreview(rendered);}
}
